// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, string calldata description) public {
        // caller must be the jojoTeam (address(0) initially) or the call will revert in both versions
        vm.assume(caller == c.jojoTeam());
        vm.prank(caller);
        bool ok = true;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: always succeeds. Mutant: always fails.
        assertTrue(ok);
    }
}

