        assertTrue(ok || caller != c.jojoTeam());
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address jojoTeam = address(0x1);
    function setUp() public {
        c = new C();
        // Set jojoTeam so we can test with it
        vm.startPrank(jojoTeam);
        c = new C();
        vm.stopPrank();
    }
    function testFuzz_property(address caller, string calldata description) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        bool expectedSuccess = (caller == c.jojoTeam());
        bool success;
        vm.prank(caller);
        try c.newEmergencyOracle(description) {
            success = true;
        } catch {
            success = false;
        }
        assertTrue(success == expectedSuccess);
    }
}
